"""Word Ladder — BFS over one-character-different neighbours.

Generating the 26 * L wildcard variants of a word is cheaper than comparing it
with every other word in the list.

Time: O(N * L^2)   Space: O(N * L)
"""
from collections import defaultdict, deque
from typing import List


class Solution:
    def ladderLength(self, beginWord: str, endWord: str, wordList: List[str]) -> int:
        words = set(wordList)
        if endWord not in words:
            return 0
        length = len(beginWord)
        buckets = defaultdict(list)
        for word in words:
            for i in range(length):
                buckets[word[:i] + "*" + word[i + 1:]].append(word)

        queue = deque([(beginWord, 1)])
        seen = {beginWord}
        while queue:
            word, steps = queue.popleft()
            if word == endWord:
                return steps
            for i in range(length):
                for nxt in buckets[word[:i] + "*" + word[i + 1:]]:
                    if nxt not in seen:
                        seen.add(nxt)
                        queue.append((nxt, steps + 1))
        return 0
